import {accountRisk,latestCloseDay,executionReview,closingISO} from './risk.js';
import {accounting,calculatePlan} from './core.js';
import {errorTags} from './execution-insights.js';
import {REVIEW_ERRORS} from './core.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>v==null||!Number.isFinite(v)?'—':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v);
const pct=v=>v==null?'—':(v*100).toFixed(2)+'%';
const names={normal:'常规运行',reduced:'半档运行',paused:'暂停新增',pending:'数据待核对'};
export function riskSummary(state,now=new Date().toISOString()){
  const r=accountRisk(state,now),p=r.progress,b=r.behavior;
  const label=b.blocked&&r.known?'暂停新增':names[r.mode],k=b.blocked?0:r.k;
  const progress=r.underlyingMode==='reduced'&&p?`<div class="recovery-progress"><span>恢复常规档：回撤 &lt;3% ${p.drawdownOK?'✓':'待满足'}</span><span>连续合规 ${p.count}/5 笔</span><span>这5笔合计 ${p.sumR>=0?'+':''}${p.sumR.toFixed(2)}R</span><span>期间无暂停 ${p.noPause?'✓':'待验收'}</span><span>${p.weekend?'周末可复核':'周末复核提档'}</span></div>`:'';
  return `<section class="risk-overview ${r.mode==='paused'||b.blocked?'risk-paused':r.mode==='reduced'?'risk-reduced':''}"><div class="risk-heading"><div><span class="micro">V1.1 / 账户风险</span><h2>${esc(label)}</h2><p>${r.known?`风险周期 ${r.cycle} · 本周期收盘回撤 <strong>${pct(r.drawdown)}</strong> · v1.1以来最大回撤 ${pct(r.historyDD)}`:esc(r.reasons[0])}</p></div><span class="tag">${k===1?'单笔1.5% / 组合3%':k===.5?'单笔0.75% / 组合1.5%':'当前不允许新增'}</span></div>${r.known?`<p class="field-note">最近核对：${esc(r.series.latest.day)}${r.series.latest.baseline?' · 启用净值':' · 收盘净值'}；只在收盘检查后降档，原持仓退出安排继续执行。</p>`:''}${b.blocked?`<p class="negative">${esc(b.reasons.join(' '))}</p>`:''}${progress}${(r.audit??[]).filter(x=>x.kind==='invalid').map(x=>`<button class="quiet-button" data-revoke-risk="${esc(x.id)}">复核已失效的恢复操作</button>`).join('')}<div class="risk-actions">${!state.workbench?.risk?.baseline?'<button id="risk-activate" class="primary-button">核对启用净值</button>':'<button id="risk-close" class="secondary-button">登记收盘净值</button>'}${r.underlyingMode==='reduced'?'<button id="risk-normal" class="quiet-button">复核恢复常规档</button>':''}${r.underlyingMode==='paused'?`<button id="risk-restart" class="quiet-button">回撤暂停复盘</button><span class="field-note">最早 ${esc(r.resumeDay??'待核对交易日历')} 美东日期恢复半档</span>`:''}${b.blocked?'<button id="behavior-recovery" class="quiet-button">连续亏损／违纪复盘</button>':''}</div></section>`;
}
export function activationForm(state,nowInput){return `<form id="risk-activate-form"><p>合并本策略所有账户，核对现金及持仓市值。无可用历史快照时，以现在核对的净值作为起点。</p><label class="full-field">启用净值 USD<input name="equity" type="number" min="0.01" step="0.01" value="${Number(state.workbench.equity)}" required></label><label class="full-field">净值核对中国时间<input name="at" type="datetime-local" step="1" value="${esc(nowInput)}" required></label><label class="inline-check"><input name="confirmed" type="checkbox" required>已核对全部策略资产与出入金，金额真实</label><button class="primary-button" type="submit">确认启用 v1.1</button><p class="field-note">保留旧成交、权益快照与初始R。启用后不能通过重复启用重设高点。</p></form>`;}
export function closeForm(state,now=new Date().toISOString(),editId=null){
  const editing=state.workbench?.risk?.closes.find(c=>c.id===editId),day=editing?editing.at.slice(0,10):latestCloseDay(now)??'',last=state.workbench?.risk?.closes.at(-1);
  return `<form id="risk-close-form" data-edit-id="${esc(editId??'')}"><p>填写美股交易日的真实收盘净值，包含所有策略账户的现金及持仓市值。</p><div class="field-grid"><label>美东交易日期<input name="day" type="date" value="${day}" ${editing?'readonly':''} required></label><label>收盘总净值 USD<input name="equity" type="number" min="0.01" step="0.01" value="${editing?.equity??''}" required></label></div><details class="compact-details"><summary>本区间有外部出入金时填写</summary><label class="full-field">每行：北京时间｜净出入金｜发生前账户净值<textarea name="flows" rows="3" placeholder="2026-10-19T21:00｜1000｜30000">${esc((editing?.flows??[]).map(f=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(f.at)).replace(' ','T')+'｜'+f.amount+'｜'+f.equityBefore).join('\n'))}</textarea></label><p class="field-note">入金正数，出金负数；策略账户间内部划转不重复计算。提供现金流发生前净值才能消除出入金对回撤的影响；无法核对时先不新增仓位。</p></details><label class="full-field">记录依据<input name="note" placeholder="券商收盘权益，已合并策略账户" value="${esc(editing?.note??'')}" required></label><button class="primary-button" type="submit">保存收盘净值</button>${last?`<p class="field-note">上一记录：${esc(last.at.slice(0,10))} · ${money(last.equity)}。缺失交易日请按顺序补齐。</p>`:''}</form>`;
}
export function recoveryForm(kind,state){
  const r=accountRisk(state),behavior=kind==='behavior',normal=kind==='normal';
  const intro=behavior?'休息期届满后，处理违纪仓位并写明下一笔买点、止损及股数。此操作不解除账户回撤降档。':normal?'只有回撤<3%、连续5笔合规完整交易合计R>0、期间无暂停且处于周末，才可恢复常规档。':'至少完整休息下一个正常交易日，退出全部持仓，确认损失原因已处理；重启后仅恢复半档，旧周期和全历史回撤保留。';
  return `<form id="risk-recovery-form" data-kind="${kind}"><p>${intro}</p>${!behavior&&!normal?'<label class="full-field">损失原因<select name="cause"><option value="strategy">合规策略亏损</option><option value="breach">主动违纪</option><option value="gap">跳空／流动性损失</option><option value="mixed">多项原因</option></select></label>':''}<label class="full-field">原因、已处理事项与下一笔执行安排<textarea name="notes" rows="5" minlength="10" required></textarea></label>${!normal?'<label class="inline-check"><input name="ordersChecked" type="checkbox" required>已核对数据、撤销新增买单，处理需退出或减回限额的仓位</label>':''}${kind==='restart'?'<label class="inline-check"><input name="causeResolved" type="checkbox" required>损失原因已处理，全部既有持仓已退出</label>':''}<button class="primary-button" type="submit">${normal?'满足条件后恢复常规档':behavior?'保存恢复复盘':'满足条件后重启半档周期'}</button><p class="field-note">${normal?'不在盘中自动提档。':`系统继续检查休息期${r.resumeDay?'及美东恢复日期 '+esc(r.resumeDay):''}，不能仅靠文字跳过。`}</p></form>`;
}
export function journalTable(rounds){
  if(!rounds.length)return '<div class="empty-state"><strong>还没有成交记录</strong><p>真实成交保存一次，退出后补充复盘。</p></div>';
  return `<div class="table-wrap"><table class="execution-table"><thead><tr><th>日期／标的</th><th>趋势／突破</th><th>买价／股数</th><th>初始止损</th><th>退出目标</th><th>实际退出</th><th>实际R</th><th>守纪／原因</th><th></th></tr></thead><tbody>${rounds.map(r=>{
    const a=accounting(r),status=executionReview(r),snapshot=r.executionModel?.inputSnapshot,trend=snapshot&&['close1h','ema20','ema50'].every(k=>Number(snapshot[k])>0)?Number(snapshot.close1h)>Number(snapshot.ema50)&&Number(snapshot.ema20)>Number(snapshot.ema50):null,breakout=snapshot&&snapshot.high&&snapshot.close30?Number(snapshot.close30)>Number(snapshot.high):null;
    const sold=a.rows.filter(x=>x.side==='sell'),qty=sold.reduce((n,x)=>n+x.qty,0),avgExit=qty?sold.reduce((n,x)=>n+x.price*x.qty,0)/qty:null,stop=Number(r.plan.stop),target=calculatePlan(r.plan).valid?calculatePlan(r.plan).target:null;
    const tags=errorTags(r),tagText=tags.length?tags.map(t=>REVIEW_ERRORS[t]).join('／'):r.review.errorTag==='none'?'已标注无偏离':'尚未标注';
    const verdict={compliant:'守纪',breach:'违纪',pending:'待核对'}[status],reason=tagText+' · '+(r.fills.flatMap(f=>[...f.violations,...(f.unverified??[])]).join('；')||r.review.notes||'待完成复盘');
    return `<tr><td><strong>${esc(r.symbol)}</strong><small>${esc((a.entryAt??r.createdAt).slice(0,10))} · ${esc(r.executionModel?.ruleVersion??'旧版')}</small></td><td>${trend===null?'待核对':trend?'通过':'不合格'}／${breakout===null?'待核对':breakout?'通过':'不合格'}</td><td>${money(Number(r.plan.entry))}<small>${r.fills.filter(f=>f.side==='buy').reduce((n,f)=>n+f.qty,0)} 股 · 剩余 ${a.qty}</small></td><td>${stop>0?money(stop):'未知'}</td><td>${money(target)}</td><td>${money(avgExit)}<small>${a.closed?'已全部退出':qty?'部分退出':'持仓中'}</small></td><td class="${a.r>0?'positive':a.r<0?'negative':''}">${a.r===null?'—':(a.r>=0?'+':'')+a.r.toFixed(2)+'R'}</td><td><span class="tag ${status==='breach'?'negative':''}">${verdict}</span><small title="${esc(reason)}">${esc(reason.slice(0,38))}${reason.length>38?'…':''}</small></td><td>${a.qty?`<button class="table-action" data-sell="${esc(r.id)}">卖出</button>`:''}<button class="table-action" data-open-record="${esc(r.id)}">详情／复盘</button></td></tr>`;
  }).join('')}</tbody></table></div>`;
}
function inline(text){return esc(text).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener noreferrer">$1 ↗</a>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');}
export function referenceHTML(markdown){
  const segment=markdown.split('## 规则依据与 reference：需要时再读')[1]?.split('## 版本记录')[0]??'';
  return segment.split(/(?=### R\d｜|### 本版未采纳|## 核实来源)/).map((section,i)=>{
    const lines=section.trim().split('\n').filter(Boolean),title=lines[0]?.replace(/^#+\s*/,''),body=lines.slice(1).map(l=>`<p>${inline(l.replace(/^- /,''))}</p>`).join('');
    return i===0?`<p>${inline(section.trim())}</p>`:`<details class="reference-item"><summary>${esc(title)}</summary>${body}</details>`;
  }).join('');
}
